import{_ as t,o as e,c as a,ag as s}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"cron 任务卡死诊断法：600s idle 死线 × 非流式无活动信号 × 端点吞吐","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-brain/cron-idle-timeout-diagnosis.md","filePath":"topics/ai-brain/cron-idle-timeout-diagnosis.md"}'),d={name:"topics/ai-brain/cron-idle-timeout-diagnosis.md"};function r(n,o,i,c,l,p){return e(),a("div",null,[...o[0]||(o[0]=[s(`<h1 id="cron-任务卡死诊断法-600s-idle-死线-×-非流式无活动信号-×-端点吞吐" tabindex="-1">cron 任务卡死诊断法：600s idle 死线 × 非流式无活动信号 × 端点吞吐 <a class="header-anchor" href="#cron-任务卡死诊断法-600s-idle-死线-×-非流式无活动信号-×-端点吞吐" aria-label="Permalink to &quot;cron 任务卡死诊断法：600s idle 死线 × 非流式无活动信号 × 端点吞吐&quot;">​</a></h1><blockquote><p>首次实证：2026-10-23，阮一峰周刊监控（job <code>cef8a9bb0aa0</code>）连续失败 定位：<code>/Users/happy/.hermes/hermes-agent/cron/scheduler.py</code>、<code>agent/agent_init.py</code> 状态：已修复并端到端验证通过</p></blockquote><hr><h2 id="一、症状与误导" tabindex="-1">一、症状与误导 <a class="header-anchor" href="#一、症状与误导" aria-label="Permalink to &quot;一、症状与误导&quot;">​</a></h2><p>飞书收到的告警文案：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>⚠️ Cron &#39;阮一峰周刊监控&#39; failed: provider timeout.</span></span>
<span class="line"><span>   Fallback chain was exhausted or unavailable.</span></span></code></pre></div><p><strong>这句话把人往错方向带</strong>：听起来像「provider 超时 + 备选链用尽」。真实错误在 cron output 文件里：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TimeoutError: Cron job &#39;阮一峰周刊监控&#39; idle for 604s (limit 600s)</span></span>
<span class="line"><span>— last activity: waiting for non-streaming API response</span></span></code></pre></div><p><strong>判据</strong>：告警文案是<strong>投递层摘要</strong>，不是根因。<strong>永远去读 <code>~/.hermes/cron/output/&lt;job_id&gt;/</code> 里最新的 <code>.md</code></strong>，尾部 <code>## Error</code> 段才是原文。</p><p>手动 <code>cronjob action=run</code> <strong>稳定复现同一错误</strong>（603s）→ 排除偶发，定性为<strong>结构性</strong>。</p><hr><h2 id="二、五步排查-每步否证一个假设" tabindex="-1">二、五步排查（每步否证一个假设） <a class="header-anchor" href="#二、五步排查-每步否证一个假设" aria-label="Permalink to &quot;二、五步排查（每步否证一个假设）&quot;">​</a></h2><h3 id="步-1-否证「环境-代理挂了」" tabindex="-1">步 1：否证「环境/代理挂了」 <a class="header-anchor" href="#步-1-否证「环境-代理挂了」" aria-label="Permalink to &quot;步 1：否证「环境/代理挂了」&quot;">​</a></h3><ul><li><code>nc -z 127.0.0.1 8899</code> → 代理活着</li><li>内网 <code>10.111.32.151:3001</code> / 公网 <code>ai.bjxm.tech:8443</code> 均正常返回（401 = 未带 key，属正常）</li><li><strong>同分钟内其它 3 个 agent 型 cron job（做梦 07:03 / 洞察 08:03 / 科学日报 09:18）全部成功</strong></li></ul><p>→ 环境健康。<strong>「同一时刻别的 job 成不成」是最快的一刀切分：都成 = 问题在本 job，都败 = 问题在环境。</strong></p><h3 id="步-2-否证「fallback-链配了但用尽」" tabindex="-1">步 2：否证「fallback 链配了但用尽」 <a class="header-anchor" href="#步-2-否证「fallback-链配了但用尽」" aria-label="Permalink to &quot;步 2：否证「fallback 链配了但用尽」&quot;">​</a></h3><p>查 <code>~/.hermes/config.yaml</code> → <code>model</code> 段只有 <code>default / provider / base_url</code> 三键，<strong><code>fallback_model</code> 与 <code>fallback_providers</code> 都没配</strong>。</p><p>→ 告警里「chain exhausted」<strong>字面属实</strong>（根本没有备选），但它<strong>不是病因</strong>：cron 的 idle watchdog 是<strong>外部杀 run</strong>，不是 provider 报错，<strong>不会触发 fallback 切换</strong>。配 fallback 是提高健壮性，治不了这个病。</p><h3 id="步-3-源码定位死线-关键" tabindex="-1">步 3：源码定位死线（关键） <a class="header-anchor" href="#步-3-源码定位死线-关键" aria-label="Permalink to &quot;步 3：源码定位死线（关键）&quot;">​</a></h3><p><code>cron/scheduler.py</code>：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">_cron_timeout </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 默认</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">_raw </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os.getenv(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HERMES_CRON_TIMEOUT&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ← 唯一覆盖通道</span></span></code></pre></div><ul><li><strong>cron 的 inactivity 上限只有 <code>HERMES_CRON_TIMEOUT</code> 这一条通道</strong>（env），<code>config.yaml</code> 无对应键，<strong>job 层也没有 timeout 字段</strong></li><li>注意区分：<code>agent.gateway_timeout</code> 默认 <strong>1800s</strong>，是另一条线；<strong>cron 只有 600s</strong>，所以 cron 比交互会话更容易被误杀</li><li>叠加放大器：<code>streaming.enabled: false</code> → <strong>整段生成期间没有任何活动信号</strong>（非流式只在响应返回时才&quot;活&quot;），<strong>单次调用的全部耗时都计入 idle</strong></li></ul><p>→ 结论：<strong>只要某一次非流式 LLM 调用耗时 &gt; 600s，必死，且与任务总时长无关。</strong></p><h3 id="步-4-端点吞吐实测-决定性" tabindex="-1">步 4：端点吞吐实测（决定性） <a class="header-anchor" href="#步-4-端点吞吐实测-决定性" aria-label="Permalink to &quot;步 4：端点吞吐实测（决定性）&quot;">​</a></h3><p>对内网端点发真实长 prompt，读 <code>usage</code> 与耗时：</p><table tabindex="0"><thead><tr><th>输入</th><th>max_tokens 上限</th><th>实际输出</th><th>耗时</th><th>备注</th></tr></thead><tbody><tr><td>8,390 tok</td><td>1024</td><td>1,024</td><td>46.5s</td><td>首请求，<code>created_cache_tokens: 8384</code></td></tr><tr><td>8,390 tok</td><td>4096</td><td>1,402</td><td>81.2s</td><td>cache 命中</td></tr><tr><td>8,390 tok</td><td>8192</td><td>1,673</td><td>79.9s</td><td>cache 命中</td></tr></tbody></table><p>→ <strong>吞吐仅 22~38 tokens/s</strong>（模型自行停在 1.4~1.7K tokens，不是被上限截断）。</p><p><strong>判据</strong>：单次生成 ~13,000 tokens 就必超 600s。而<strong>大累积上下文还会额外抬高 prefill 成本</strong>（每轮上下文都在变 → cache 常重建）。</p><h3 id="步-5-prompt-体积审计" tabindex="-1">步 5：prompt 体积审计 <a class="header-anchor" href="#步-5-prompt-体积审计" aria-label="Permalink to &quot;步 5：prompt 体积审计&quot;">​</a></h3><p>该 job 的 cron output 档 <strong>69KB</strong>，拆开看：</p><ul><li><code>ai-brain-workflow</code> skill <strong>全文 ~20K tokens</strong>，<strong>每一轮请求都随上下文重发</strong></li><li>原 prompt 要求「<strong>一次生成</strong>整篇 1500 字提炼长文」</li></ul><p>→ 大上下文 × 慢 prefill × 非流式无信号 = <strong>结构性踩线</strong>。10-19~10-22 能过，只是余量没耗尽。</p><hr><h2 id="三、修复-五项" tabindex="-1">三、修复（五项） <a class="header-anchor" href="#三、修复-五项" aria-label="Permalink to &quot;三、修复（五项）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>动作</th><th>生效方式</th></tr></thead><tbody><tr><td>①</td><td><code>skills=[]</code> —— 拿掉 skill 全文（关键落盘规范原 prompt 已内嵌）</td><td>立即（每 tick 重读 job）</td></tr><tr><td>②</td><td>prompt 改为<strong>分节增量写入</strong>：<code>write_file</code> 写「头 + 本期主文」→ <code>patch</code> 追加「动态/文章/工具/资源/言论」→ <code>patch</code> 追加「跨主题关联 + 关键词行」，<strong>明令禁止一次生成整篇</strong></td><td>立即</td></tr><tr><td>③</td><td>抓正文改走 <code>api.github.com</code> + <code>Accept: application/vnd.github.raw</code>（raw.githubusercontent 降为备选）；<code>auto_link.py</code> 改 <code>--daily</code></td><td>立即</td></tr><tr><td>④</td><td>launchd plist 加 <code>HERMES_CRON_TIMEOUT=1800</code>（对齐 gateway 的 30 分钟）</td><td><strong>需 gateway 重启</strong></td></tr><tr><td>⑤</td><td>job pin <code>model=deepseek-v4.1-flash</code> / <code>provider=123-copy</code>（原本 <code>model: null</code>，但<strong>有 <code>model_snapshot</code></strong> → 主模型一换就会被 <strong>drift guard 静默跳过</strong>）</td><td>立即</td></tr></tbody></table><p><strong>验证</strong>：改后手动 run → <code>last_status: ok</code>；产物 <code>topics/ai-system-architecture/weekly-416-analysis.md</code>（36.7KB / 209 行，含一手核实记录）+ index 条目 + commit <code>bf2b457</code> 已推送（本地 HEAD == <code>origin/main</code>）✔</p><hr><h2 id="四、通用判据-可复用" tabindex="-1">四、通用判据（可复用） <a class="header-anchor" href="#四、通用判据-可复用" aria-label="Permalink to &quot;四、通用判据（可复用）&quot;">​</a></h2><ol><li><strong>告警文案 ≠ 根因</strong>：去读 <code>cron/output/&lt;job_id&gt;/*.md</code> 的 <code>## Error</code> 原文。</li><li><strong>一刀切分环境与本 job</strong>：同一时刻其它 job 的成功率。</li><li><strong>cron 的死线只有 600s（<code>HERMES_CRON_TIMEOUT</code>），比交互会话的 1800s 更紧</strong>。长任务要么减负，要么放宽这条线。</li><li><strong><code>streaming.enabled: false</code> 时，&quot;总耗时&quot;既是&quot;idle 时间&quot;</strong> —— 长任务的第一嫌疑就是这个组合。</li><li><strong>每轮重发的 skill 全文是隐性上下文税</strong>：一个 job 需不需要整个 skill，值得单独审。</li><li><strong>能分节写就不要一次生成整篇</strong>：把单次输出压到几百 tokens，是抗死线最直接的手段。</li><li><strong>unpinned job 有漂移风险</strong>：<code>model: null</code> + <code>model_snapshot</code> 存在时，改主模型会让 job <strong>静默跳过</strong>。要稳定就显式 pin。</li></ol><hr><h2 id="五、踩坑记录" tabindex="-1">五、踩坑记录 <a class="header-anchor" href="#五、踩坑记录" aria-label="Permalink to &quot;五、踩坑记录&quot;">​</a></h2><ul><li><strong><code>cronjob action=update</code> 的 <code>model</code> 参数必须是对象</strong>：<code>{&quot;model&quot;: &quot;...&quot;, &quot;provider&quot;: &quot;...&quot;}</code>。传字符串会被 <code>_resolve_model_override()</code> 静默丢弃（<code>isinstance(model_obj, dict)</code> 不成立）→ 表现为「设了没反应」。<code>provider</code> 是独立顶层参数，所以它生效、model 不生效，<strong>极易误判成工具 bug</strong>。</li><li><strong>patch 工具拒改 <code>~/.hermes/config.yaml</code></strong>（安全策略），要走 <code>hermes config set</code>；但 CLI <strong>不支持列表值</strong>（会把 <code>[{...}]</code> 存成<strong>字符串</strong>，且提示正确键名是 <code>fallback_providers</code>，<code>fallback_model</code> 只是 legacy 别名）→ 列表类配置仍需手工编辑 config.yaml。</li><li><strong>provider 默认模型可能坏掉而不报警</strong>：<code>123-copy</code> 的 <code>model: deepseek-v4-flash-0731</code> 实测 <strong>HTTP 503</strong>；<code>grok-46</code>（127.0.0.1:8787）也 503。同端点实测可用备选：<code>qwen3.7-max</code> <strong>0.9s</strong> / <code>deepseek-v4-pro</code> <strong>3.6s</strong>；<code>glm-5.3-flash</code> <strong>62s 且空回复，不可用</strong>。</li><li><strong>纠正旧记</strong>：<code>raw.githubusercontent.com</code> <strong>并非恒不可达</strong>（本次 HTTP 200 / 0.7s，与 api.github.com 取得字节数一致）。可达性随代理状态变化，不应记为「永久不通」。</li><li>原 prompt 已备份：<code>~/.hermes/state/cef8a9bb0aa0.prompt.bak.md</code></li></ul><p>关键词：cron idle timeout、HERMES_CRON_TIMEOUT、600s 死线、非流式无活动信号、streaming.enabled false、provider timeout 告警误导、fallback chain exhausted、端点吞吐实测、22 tokens每秒、skill 全文上下文税、分节增量写入、prompt 减负、api.github.com raw Accept、cronjob update model 传对象、drift guard 静默跳过、launchd plist 环境变量、deepseek-v4-flash-0731 503</p><p>关联：<code>topics/ai-brain/cron-outage-2026-09-23.md</code>、<code>topics/ai-brain/index.md</code>、<code>topics/ai-brain/auto-link-quality-fixes.md</code>、<code>topics/ai-system-architecture/weekly-416-analysis.md</code></p>`,44)])])}const u=t(d,[["render",r]]);export{h as __pageData,u as default};
